import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface Project {
  id: string;
  title: string;
  category: string;
  description: string;
  imageUrl: string;
  year: string;
}

export interface Service {
  title: string;
  description: string;
  icon: React.ReactNode;
}

export interface Message {
  role: 'user' | 'model';
  text: string;
}

import { GoogleGenAI } from "@google/genai";

const SYSTEM_INSTRUCTION = `
You are the AI Concierge for Yamasaka Horizon (山坂ホライゾン).
Your tone is professional, sophisticated, minimalist, and helpful, reflecting the premium quality of Japanese architecture and real estate consulting.

About Yamasaka Horizon:
- We provide architectural design, real estate development, and consulting services.
- Our philosophy is "Connecting Horizon with Architecture," focusing on minimalist beauty and functionality.
- We specialize in high-end residential projects and urban renovation.

Your tasks:
1. Answer visitor questions about architectural design, real estate trends in Japan, and our services.
2. Be polite and use appropriate Japanese (Keigo) when responding in Japanese, but also be capable of English interaction.
3. Keep responses concise but insightful.
4. If asked about contact, direct them to the contact form on the page.

If you don't know an answer specifically about the company's internal data, provide general high-quality architectural advice.
`;

export class GeminiService {
  private ai: GoogleGenAI;

  constructor() {
    this.ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });
  }

  async chat(history: { role: 'user' | 'model', parts: { text: string }[] }[], prompt: string) {
    try {
      const response = await this.ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: [...history, { role: 'user', parts: [{ text: prompt }] }],
        config: {
          systemInstruction: SYSTEM_INSTRUCTION,
          temperature: 0.7,
        },
      });

      return response.text || "申し訳ございません。現在応答することができません。";
    } catch (error) {
      console.error("Gemini API Error:", error);
      return "エラーが発生しました。しばらくしてから再度お試しください。";
    }
  }
}

export const geminiService = new GeminiService();

import React, { useState, useEffect } from 'react';
import { Navbar } from './components/Navbar';
import { Hero } from './components/Hero';
import { Services } from './components/Services';
import { Portfolio } from './components/Portfolio';
import { About } from './components/About';
import { Contact } from './components/Contact';
import { Footer } from './components/Footer';
import { AIConcierge } from './components/AIConcierge';

const App: React.FC = () => {
  const [isScrolled, setIsScrolled] = useState(false);

  useEffect(() => {
    const handleScroll = () => {
      setIsScrolled(window.scrollY > 50);
    };
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  return (
    <div className="min-h-screen">
      <Navbar isScrolled={isScrolled} />

      <main>
        <section id="hero">
          <Hero />
        </section>

        <section id="services" className="py-24 bg-white">
          <Services />
        </section>

        <section id="portfolio" className="py-24 bg-slate-50">
          <Portfolio />
        </section>

        <section id="about" className="py-24 bg-white">
          <About />
        </section>

        <section id="contact" className="py-24 bg-slate-900 text-white">
          <Contact />
        </section>
      </main>

      <Footer />

      {/* Integrated AI Assistant */}
      <AIConcierge />
    </div>
  );
};

export default App;

