import { GoogleGenAI, GenerateContentResponse } from "@google/genai";

const SYSTEM_INSTRUCTION = `
あなたは山坂ホライゾン（Yamasaka Horizon）のAIコンシェルジュです。
当社は、スポーツ・エンターテインメント業界に特化したコンサルティングファームです。

事業内容:
1. スポーツ・エンタメ業界におけるマーケティングやDXに関するコンサルティング、アウトソーシング
   - スタジアムのスマート化、ファンデータの活用、デジタルマーケティング戦略の立案など。
2. テック系企業におけるスポーツ・エンタメ事業参入、拡大支援
   - テクノロジー企業の持つ技術をどうスポーツ界に適合させるかの戦略立案。
3. スポーツ・エンタメ業界におけるマーケティングやDXに関する教育
   - セミナーの開催、大学での講義、次世代リーダーの育成。

トーン:
- プロフェッショナル、先端的、知的、かつ情熱的。
- 丁寧な日本語（敬語）を使用。

回答の指針:
- スポーツビジネスやDX、最新のマーケティングトレンドに基づいた洞察を提供してください。
- 会社への具体的な問い合わせやセミナー依頼については、ページ下部のコンタクトフォームを案内してください。
`;

export class GeminiService {
  async chat(history: { role: 'user' | 'model', parts: { text: string }[] }[], prompt: string) {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    try {
      const response: GenerateContentResponse = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: [...history, { role: 'user', parts: [{ text: prompt }] }],
        config: {
          systemInstruction: SYSTEM_INSTRUCTION,
          temperature: 0.7,
        },
      });

      return response.text || "申し訳ございません。現在応答することができません。";
    } catch (error) {
      console.error("Gemini API Error:", error);
      return "エラーが発生しました。しばらくしてから再度お試しください。";
    }
  }
}

export const geminiService = new GeminiService();

