                if (link.name === 'HOME') {
                  e.preventDefault();
                  onNavigateHome();
                }
              }}
              className={`text-[10px] lg:text-xs font-bold tracking-[0.2em] transition-colors hover:text-blue-600 ${
                isScrolled ? 'text-slate-700' : 'text-slate-700'
              }`}
