type ViewState = 'home' | 'news-list' | 'services-list' | 'portfolio-list' | 'about-page' | 'contact-page' | 'detail';

const App: React.FC = () => {
  const [isScrolled, setIsScrolled] = useState(false);
  const [view, setView] = useState<ViewState>('home');
  const [detailTitle, setDetailTitle] = useState('');

  useEffect(() => {
    const handleScroll = () => {
      setIsScrolled(window.scrollY > 50);
    };
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  const navigate = (newView: ViewState, title: string = '') => {
    setDetailTitle(title);
    setView(newView);
    window.scrollTo(0, 0);
  };

  return (
    <div className="min-h-screen bg-white">
      <Navbar 
        isScrolled={isScrolled} 
        onNavigate={(v) => navigate(v as ViewState)} 
      />

      <main>
        {view === 'home' && (
          <>
            <section id="hero">
              <Hero />
            </section>

            {/* NEWS Section: Adjusted for mobile peeking (approx 70-75vh hero means this shows up) */}
            <section id="news" className="py-12 bg-white border-b border-slate-50 relative z-20 shadow-[-20px_0_40px_rgba(0,0,0,0.03)]">
              <News onViewAll={() => navigate('news-list')} />
            </section>

            <section id="services" className="py-20 bg-slate-50/50">
              <Services onSelect={(t) => navigate('detail', t)} />
            </section>

            <section id="portfolio" className="py-20 bg-white">
              <Portfolio onSelect={(t) => navigate('detail', t)} />
            </section>

            <section id="about" className="py-20 bg-slate-50/30">
              <About />
            </section>

            <section id="contact" className="py-20 bg-slate-900 text-white">
              <Contact />
            </section>
          </>
        )}

        {view === 'news-list' && <NewsListPage onBack={() => navigate('home')} />}
        {view === 'services-list' && <ServicesListPage onBack={() => navigate('home')} onSelect={(t) => navigate('detail', t)} />}
        {view === 'portfolio-list' && <PortfolioListPage onBack={() => navigate('home')} onSelect={(t) => navigate('detail', t)} />}
        {view === 'about-page' && <AboutPage onBack={() => navigate('home')} />}
        {view === 'contact-page' && <ContactPage onBack={() => navigate('home')} />}
        {view === 'detail' && <DetailPage title={detailTitle} onBack={() => navigate('home')} />}
      </main>

      <Footer />
      <AIConcierge />
    </div>
  );
};

export default App;

import React, { useState } from 'react';

interface NavbarProps {
  isScrolled: boolean;
  onNavigate: (view: string) => void;
}

export const Navbar: React.FC<NavbarProps> = ({ isScrolled, onNavigate }) => {
  const [isOpen, setIsOpen] = useState(false);

  const navLinks = [
    { name: 'HOME', view: 'home', href: '#hero' },
    { name: 'SERVICES', view: 'services-list', href: '#services' },
    { name: 'PORTFOLIO', view: 'portfolio-list', href: '#portfolio' },
    { name: 'ABOUT', view: 'about-page', href: '#about' },
    { name: 'NEWS', view: 'news-list', href: '#news' },
    { name: 'CONTACT', view: 'contact-page', href: '#contact' },
  ];

  const handleLinkClick = (e: React.MouseEvent, view: string) => {
    // If we're already on home, let the default anchor behavior work for smooth scroll
    // But we still call onNavigate to ensure the internal state is correct if needed
    if (view === 'home') {
      onNavigate('home');
    } else {
      e.preventDefault();
      onNavigate(view);
    }
    setIsOpen(false);
  };

  return (
    <nav className={`fixed w-full z-50 transition-all duration-300 ${
      isScrolled ? 'glass-morphism py-4 shadow-sm' : 'bg-transparent py-6'
    }`}>
      <div className="max-w-7xl mx-auto px-6 md:px-12 flex justify-between items-center">
        <div className="flex items-center space-x-2 cursor-pointer" onClick={() => onNavigate('home')}>
          <span className={`text-xl md:text-2xl font-bold tracking-tighter transition-colors ${
            isScrolled ? 'text-slate-900' : 'text-slate-800'
          }`}>
            YAMASAKA <span className="font-light text-slate-400">HORIZON</span>
          </span>
        </div>

        {/* Desktop Nav */}
        <div className="hidden md:flex space-x-8 lg:space-x-10">
          {navLinks.map((link) => (
            <a
              key={link.name}
              href={link.href}
              onClick={(e) => handleLinkClick(e, link.view)}
              className={`text-[10px] lg:text-xs font-bold tracking-[0.2em] transition-colors hover:text-blue-600 ${
                isScrolled ? 'text-slate-700' : 'text-slate-700'
              }`}
            >
              {link.name}
            </a>
          ))}
        </div>

        {/* Mobile Toggle */}
        <button 
          className="md:hidden text-slate-900"
          onClick={() => setIsOpen(!isOpen)}
        >
          <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d={isOpen ? "M6 18L18 6M6 6l12 12" : "M4 6h16M4 12h16M4 18h16"} />
          </svg>
        </button>
      </div>

      {/* Mobile Menu */}
      {isOpen && (
        <div className="md:hidden absolute top-full left-0 w-full bg-white border-t border-slate-100 p-6 flex flex-col space-y-4 shadow-xl">
          {navLinks.map((link) => (
            <a
              key={link.name}
              href={link.href}
              className="text-sm font-medium tracking-widest text-slate-900 py-2 border-b border-slate-50 last:border-none"
              onClick={(e) => handleLinkClick(e, link.view)}
            >
              {link.name}
            </a>
          ))}
        </div>
      )}
    </nav>
  );
};

